/* ─── Avatar, tag, stat ─── */
.avatar { display: inline-grid; place-items: center; width: 32px; height: 32px; flex: none; background: var(--foreground); color: var(--background); font-size: var(--text-xs); font-weight: var(--weight-medium); text-transform: uppercase; overflow: hidden; }
.avatar img { width: 100%; height: 100%; object-fit: cover; }
.avatar-sm { width: 24px; height: 24px; font-size: var(--text-xs); }
.avatar-lg { width: 48px; height: 48px; font-size: var(--text-sm); }
.avatar-line { background: transparent; color: var(--foreground); box-shadow: inset 0 0 0 1px var(--foreground); }
.avatar-group { display: inline-flex; }
.avatar-group > .avatar { box-shadow: 0 0 0 2px var(--background); }
.avatar-group > .avatar + .avatar { margin-inline-start: calc(-1 * var(--s2)); }
.tag { overflow-wrap: anywhere; display: inline-flex; align-items: center; gap: var(--s2); padding: 2px var(--s3); font-size: var(--text-sm); box-shadow: inset 0 0 0 1px var(--rule); }
.tag button { min-inline-size: 24px; min-block-size: 24px; /* WCAG 2.5.8 target size; found by e2e */ padding: 0 var(--s1); color: var(--muted); }
.tag button:hover { color: var(--foreground); }
.stat { display: grid; gap: var(--s1); align-content: start; /* a Stat without a note must not stretch its rows in a taller grid cell */ }
.stat-value { font-family: var(--font-display); font-weight: var(--weight-bold); font-size: var(--display-sm); letter-spacing: -0.03em; line-height: 1; }
.stat-note { font-size: var(--text-sm); color: var(--muted); }

/* Tags input: a bordered box holding tags and a bare text input. */
.tags-input { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s2); width: 100%; min-height: var(--s7); padding: var(--s2) var(--s3); border: 1px solid var(--foreground); border-radius: var(--radius); }
.tags-input:focus-within { outline: var(--focus-ring); }
.tags-input[data-invalid] { border-color: var(--danger); }
.tags-input[data-disabled] { opacity: var(--opacity-disabled); }
.tags-input-field { flex: 1 1 8ch; min-width: 8ch; padding: var(--s1) 0; background: transparent; border: 0; color: var(--foreground); outline: 0; }
.tags-input-field::placeholder { color: var(--muted); }
.tags-input[data-size="sm"] { min-height: var(--control-sm); }
.tags-input[data-size="lg"] { min-height: var(--control-lg); }

